package net.civeira.phylax.features.access.userinvitation.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userinvitation.domain.UserInvitation;
import net.civeira.phylax.features.access.userinvitation.domain.event.UserInvitationEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserInvitationEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserInvitationEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserInvitation entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
